+import { createHash, randomUUID } from "node:crypto";
+import { appendFile, mkdir, readFile } from "node:fs/promises";
+import { join, resolve } from "node:path";
+
+/**
+ * R-14 Agent memory, phase 1 slice 1: persist per-repo lessons across sessions.
+ *
+ * Storage is append-only JSONL under `config.memory.dir`, keyed by a hash of the
+ * repo root so paths never leak into filenames. Every write is mirrored to an
+ * audit log so admins can see what the agent remembered and why.
+ *
+ * TODO(R-14): wire FileMemoryStore into the CLI/IDE entrypoints when config.memory.enabled.
+ * TODO(R-14): ingest PR review comments, user corrections, and ADRs as sources.
+ * TODO(R-14): admin list/edit/delete API + policy scoping (org / repo / user).
+ * TODO(R-14): embedding-based recall via VectorIndex instead of keyword overlap.
+ * TODO(R-14): retention/TTL and redaction of secrets before write.
+ */
+
+export type MemoryKind = "lesson";
+
+export interface MemoryEntry {
+  id: string;
+  repoKey: string;
+  kind: MemoryKind;
+  text: string;
+  sourceSessionId: string;
+  createdAt: number;
+}
+
+export interface MemoryStore {
+  recall(repoRoot: string, task: string, limit: number): Promise<MemoryEntry[]>;
+  saveLessons(repoRoot: string, sessionId: string, lessons: string[]): Promise<void>;
+}
+
+export const repoKeyFor = (repoRoot: string): string =>
+  createHash("sha256").update(resolve(repoRoot)).digest("hex").slice(0, 16);
+
+const tokenize = (s: string): Set<string> =>
+  new Set(s.toLowerCase().split(/[^a-z0-9_]+/).filter((w) => w.length > 2));
+
+export class FileMemoryStore implements MemoryStore {
+  constructor(private readonly dir: string) {}
+
+  async recall(repoRoot: string, task: string, limit: number): Promise<MemoryEntry[]> {
+    const entries = await this.load(repoKeyFor(repoRoot));
+    const query = tokenize(task);
+    const score = (e: MemoryEntry): number =>
+      [...tokenize(e.text)].filter((w) => query.has(w)).length;
+    // Overlap first, then most recent. Repo-wide conventions with zero overlap
+    // still surface by recency, which is what customers asked for.
+    return [...entries]
+      .sort((a, b) => score(b) - score(a) || b.createdAt - a.createdAt)
+      .slice(0, limit);
+  }
+
+  async saveLessons(repoRoot: string, sessionId: string, lessons: string[]): Promise<void> {
+    const repoKey = repoKeyFor(repoRoot);
+    const known = new Set((await this.load(repoKey)).map((e) => e.text));
+    const fresh = lessons.filter((l) => !known.has(l));
+    if (fresh.length === 0) return;
+
+    const now = Date.now();
+    const entries: MemoryEntry[] = fresh.map((text) => ({
+      id: randomUUID(),
+      repoKey,
+      kind: "lesson",
+      text,
+      sourceSessionId: sessionId,
+      createdAt: now,
+    }));
+
+    await mkdir(join(this.dir, repoKey), { recursive: true });
+    await appendFile(this.lessonsPath(repoKey), entries.map((e) => JSON.stringify(e)).join("\n") + "\n");
+    await appendFile(
+      join(this.dir, "audit.jsonl"),
+      entries.map((e) => JSON.stringify({ at: now, action: "create", entryId: e.id, repoKey, sessionId })).join("\n") + "\n",
+    );
+  }
+
+  private lessonsPath(repoKey: string): string {
+    return join(this.dir, repoKey, "lessons.jsonl");
+  }
+
+  private async load(repoKey: string): Promise<MemoryEntry[]> {
+    let raw: string;
+    try {
+      raw = await readFile(this.lessonsPath(repoKey), "utf8");
+    } catch (err) {
+      if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
+      throw err;
+    }
+    return raw
+      .split("\n")
+      .filter(Boolean)
+      .map((line) => JSON.parse(line) as MemoryEntry);
+  }
+}

