+/**
+ * Memory failures must never fail a task: log and carry on with no recall.
+ * TODO(R-14): emit telemetry for memory errors instead of console.warn.
+ */
+async function recallLessons(
+  memory: MemoryStore | undefined,
+  repoRoot: string,
+  task: string,
+): Promise<string[]> {
+  if (!memory) return [];
+  try {
+    const entries = await memory.recall(repoRoot, task, 10);
+    return entries.map((e) => e.text);
+  } catch (err) {
+    console.warn(`[forgeline] memory recall failed: ${(err as Error).message}`);
+    return [];
+  }
+}
+
+async function persistLessons(
+  memory: MemoryStore | undefined,
+  repoRoot: string,
+  sessionId: string,
+  outcome: TaskOutcome,
+): Promise<void> {
+  if (!memory || outcome.lessons.length === 0) return;
+  try {
+    // TODO(R-14): persist the full outcome (status, prUrl) for "similar past task" recall.
+    await memory.saveLessons(repoRoot, sessionId, outcome.lessons);
+  } catch (err) {
+    console.warn(`[forgeline] memory persist failed: ${(err as Error).message}`);
+  }
+}
